-- Batch 3 part 2 (players 951-1000), 2026-10-09: clubs the career-stats extractor could not link.
-- Apply AFTER players_batch3_part2_stats.sql. Safe to repeat.
-- Adds the real clubs missing from the pool (scope = country, no badge or aliases) and points
-- these players' career rows at them. Reserve, B and feeder teams (Barcelona B, Bilbao Athletic,
-- Basconia, Villarreal C ...) are left unlinked on purpose, as in earlier batches. So is
-- Bastoni's nameless '(row 5)' row, an artefact of his article's infobox.

-- PART 1: new clubs.
INSERT INTO entities (canonical_name, entity_type, scope) SELECT 'Ascoli', 'club', 'Italy' WHERE NOT EXISTS (SELECT 1 FROM entities WHERE entity_type = 'club' AND canonical_name = 'Ascoli' AND scope = 'Italy');
INSERT INTO entities (canonical_name, entity_type, scope) SELECT 'Bodø/Glimt', 'club', 'Norway' WHERE NOT EXISTS (SELECT 1 FROM entities WHERE entity_type = 'club' AND canonical_name = 'Bodø/Glimt' AND scope = 'Norway');
