INSERT INTO entities (canonical_name, entity_type, scope) SELECT 'Rosenborg', 'club', 'Norway' WHERE NOT EXISTS (SELECT 1 FROM entities WHERE entity_type = 'club' AND canonical_name = 'Rosenborg' AND scope = 'Norway');
