-- PART 2: link career rows (players 951-1000 only) to the new clubs.
UPDATE player_career_stats SET team_id = (SELECT id FROM entities WHERE entity_type = 'club' AND canonical_name = 'Ascoli' AND scope = 'Italy') WHERE player_id BETWEEN 951 AND 1000 AND competition_type = 'club' AND team_id IS NULL AND team_name_raw IN ('Ascoli', '→ Ascoli (loan)', 'Ascoli (loan)', '→ Ascoli');
